@import 'tailwindcss';
@source '../**/*.{js,ts,jsx,tsx}';

@import 'tw-animate-css';

@import './fonts.css';
@import './tailwind.css';
@import './theme.css';

import { useState } from 'react';
import { Layout } from './components/Layout';
import { Login } from './components/Login';
import { Dashboard } from './components/Dashboard';
import { StationMap } from './components/StationMap';
import { FrequencyPlanning } from './components/FrequencyPlanning';
import { StationStats } from './components/StationStats';
import { LicenseAnalysis } from './components/LicenseAnalysis';
import { DataManagement } from './components/DataManagement';
import { SystemManagement } from './components/SystemManagement';

export default function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentPage, setCurrentPage] = useState<string>('dashboard');

  const handleLogin = () => {
    setIsLoggedIn(true);
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setCurrentPage('dashboard');
  };

  if (!isLoggedIn) {
    return <Login onLogin={handleLogin} />;
  }

  const renderPage = () => {
    switch (currentPage) {
      case 'dashboard':        return <Dashboard />;
      case 'station-map':      return <StationMap />;
      case 'frequency-planning': return <FrequencyPlanning />;
      case 'station-stats':    return <StationStats />;
      case 'license-analysis': return <LicenseAnalysis />;
      case 'data-management':  return <DataManagement />;
      case 'system-management': return <SystemManagement />;
      default:                 return <Dashboard />;
    }
  };

  return (
    <Layout
      currentPage={currentPage}
      onNavigate={setCurrentPage}
      onLogout={handleLogout}
    >
      {renderPage()}
    </Layout>
  );
}

# License Analysis 实现计划

> **For agentic workers:** REQUIRED SUB-SKILL: Use superpowers:subagent-driven-development (recommended) or superpowers:executing-plans to implement this plan task-by-task. Steps use checkbox (`- [ ]`) syntax for tracking.

**Goal:** 将 License Analysis 页面从本地 Mock 数据接入真实后端 API，实现 Usage Rate Analysis / License Count Statistics / Licensed Station Count / Validity Period Statistics 四个 Tab 的数据全部来自后端。

**Architecture:**
- 后端在 `StatisticsController` 新增支持多维度查询的统计接口（按月份/业务类型/省份/年份筛选），在 `PermitController` 确认分页查询支持详情筛选
- 前端新增 `api/statistics.ts` API 层，在 `LicenseAnalysis.tsx` 中用 `useEffect` + `useState` 替代硬编码 mock 数据
- 数据映射：后端 `status` 字段（active/expired/revoked）→ 前端 UI 状态（normal/expiring/expired），通过计算 `enddate` 与当前日期的差值判断

**Tech Stack:** React + TypeScript + Recharts (前端), Spring Boot + MyBatis-Plus (后端), MySQL 8.0

---

