// frontend/src/app/api/station.ts
const BASE_URL = 'http://localhost:8084/api';

const request = async (url: string, options: RequestInit = {}) => {
  const token = localStorage.getItem('token');
  const headers: HeadersInit = {
    'Content-Type': 'application/json',
    ...options.headers,
  };
  if (token) {
    headers['Authorization'] = `Bearer ${token}`;
  }

  const response = await fetch(`${BASE_URL}${url}`, {
    ...options,
    headers,
  });

  if (!response.ok) {
    const error = await response.json().catch(() => ({ message: 'Unknown error' }));
    throw new Error(error.message || 'Request failed');
  }

  return response.json();
};

// StationMapVO 对应的前端类型
export interface StationMapVO {
  guid: string;
  sitename: string;
  longitude: number;
  latitude: number;
  type: string;
  stationtype: string;
  frequency: string;     // "1800–1900 MHz"
  freqMHz: number;        // 中心频率数值
  unit: string;           // 设台单位
  equipName: string;      // 设备名称
  equipModel: string;     // 设备型号
  expiry: string;         // "2027-06-30"
  power: string;          // "20 W"
  status: 'normal' | 'expiring' | 'expired';
  province: string;
}

// Station 编辑更新 DTO
export interface StationUpdate {
  type?: string;
  technology?: string;
  stationtype?: string;
  frequencyt?: number;
  frequencyr?: number;
  bandwidth?: number;
  devicemodel?: string;
  outputpower?: number;
  province?: string;
  district?: string;
  location?: string;
  sitename?: string;
  longitude?: number;
  latitude?: number;
  startdate?: string;
  expirationdate?: string;
  unit?: string;
  equipname?: string;
}

export const stationApi = {
  // 获取地图台站列表
  getMapPoints: () => request('/station/map'),

  // 更新台站（用于保存编辑）
  update: (id: string, data: StationUpdate) =>
    request(`/station/${id}`, { method: 'PUT', body: JSON.stringify(data) }),
};
```

