        type: r.type ?? '',
        region: r.district ?? '',
        province: r.province ?? '',
        detailedLocation: r.location ?? '',
        frequency: buildFrequencyString(r.frequencyt, r.frequencyr),
        status: computeStatus(r.expirationdate),
        openDate: r.startdate ?? '',
        expireDate: r.expirationdate ?? '',
