const convertToFrequencyBand = (vo: PlanningVO): FrequencyBand => ({
  guid: vo.guid,
  category: vo.radioservices,
  subCategory: vo.subservices,
  service: vo.level,
  bandName: vo.segmentname,
  startFreq: vo.startfrequency,
  endFreq: vo.stopfrequency,
